function UITalentMaterialGetRewardNode:FillSelf()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    if not vo then
        return
    end
    local copyVo = QuestConfMgr:GetInstance():GetTalentCopyVo(vo.group)
    if copyVo then
    end
    CfUtils.FillText(self.TxtName, vo.name) --"P-"..vo.pos)

    local curQuestId = QuestConfMgr:GetInstance():GetTalentCurChallengeQuestId()  --当前应该打的

    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curQuestId)
    KTool.SetActive(self.NoClearance, not isPass)
    local buffId = talentQuestComponent:GetBuffIdByQuestId(self._curQuestId)
    if isPass then
        local num = QuestConfMgr:GetInstance():GetTalentRewardOutPutByQuestId(vo.group, self._curQuestId)
        local id = QuestConfMgr:GetInstance():GetTalentRewardId()
        local rewardVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        CfUtils.RefeshGoodGo(self.GoodNode, id, num, 0.9, nil, function()
            --GameUtils.ShowCommonGoodsTipsBoard(self.GoodNode, id, true, GoodsUtils.GetThingNo(id))
            vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
            GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, nil, nil, id)
        end)

        local canvas = self.controller.gameObject:GetComponent(typeof(CanvasGroup))
        canvas.alpha = 0.5
    elseif checkNumber(curQuestId) == checkNumber(self._curQuestId) then
        local num = QuestConfMgr:GetInstance():GetTalentRewardOutPutByQuestId(vo.group, self._curQuestId)
        local id = QuestConfMgr:GetInstance():GetTalentRewardId()
        local rewardVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        CfUtils.RefeshGoodGo(self.GoodNode, id, num, 0.9, nil, function()
            --GameUtils.ShowCommonGoodsTipsBoard(self.GoodNode, id, true, GoodsUtils.GetThingNo(id))
            vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
            GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, nil, nil, id)
        end)
        KTool.SetActive(self.NoClearance, false)

        if buffId then
            local buffVo = QuestConfMgr:GetInstance():GetTalentBuffVo(buffId)
            if buffVo then
                CfUtils.FillText(self.TxtNumber, checkInt(checkNumber(buffVo.rewardRatio) * 100).."%")
            end
        end

        KTool.SetActive(self.ImgbgIncrease, true)
        KTool.SetActive(self.ImgCurrent, true)
    else
        KTool.SetActive(self.GoodNode, false)
        local curChallengeQuestId = checkNumber(QuestConfMgr:GetInstance():GetTalentCurChallengeQuestId())
        if curChallengeQuestId == checkNumber(self._curQuestId) then
            KTool.SetActive(self.ImgCurrent, true)
            if buffId then
                local num = QuestConfMgr:GetInstance():GetTalentRewardOutPutByQuestId(vo.group, self._curQuestId)
                local id = QuestConfMgr:GetInstance():GetTalentRewardId()
                CfUtils.RefeshGoodGo(self.GoodNode, id, num, 0.9, nil, function()
                    --GameUtils.ShowCommonGoodsTipsBoard(self.GoodNode, id, true, GoodsUtils.GetThingNo(id))
                    vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
                    GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, nil, nil, id)
                end)
                
                local buffVo = QuestConfMgr:GetInstance():GetTalentBuffVo(buffId)
                if buffVo then
                    KTool.SetActive(self.TxtIncrease, true)
                    CfUtils.FillText(self.TxtNumber, "<size=24>"..checkInt(checkNumber(buffVo.rewardRatio) * 100).."%</size>")
                end
            end
